    merged = dict(base)
    for k, v in override.items():
        if k in merged and isinstance(merged[k], dict) and isinstance(v, dict):
            # Deep merge dictionaries
            merged[k] = merge_step_args(merged[k], v)
        elif k in merged and isinstance(merged[k], list) and isinstance(v, list):
            # Concatenate lists, ensuring base elements are not omitted
            # This is crucial for retaining mandatory flags, as per INC-9203
            merged[k] = merged[k] + v
        else:
            # For other types, or type mismatches, override the base value
            merged[k] = v
